from json import dumps


class Tree:
    def __init__(self, label, children=None):
        self.label = label
        self.children = children if children is not None else []

    def __dict__(self):
        return {self.label: [c.__dict__() for c in sorted(self.children)]}

    def __str__(self, indent=None):
        return dumps(self.__dict__(), indent=indent)

    def __lt__(self, other):
        return self.label < other.label

    def __eq__(self, other):
        return self.__dict__() == other.__dict__()

    def from_pov(self, from_node):
        """Return a copy of the tree rooted at ``from_node``.

        The tree is stored with edges pointing from a root towards its
        children.  To re-root it, the edges on the path from the current root
        to ``from_node`` have to be reversed.  Building the result from the
        undirected view of the original tree does that naturally and, at the
        same time, leaves the original tree untouched.
        """
        # Record each node's parent in the input orientation.  Tree instances
        # are deliberately not used as dictionary keys (they define __eq__),
        # so object ids are used for identity-based bookkeeping instead.
        parents = {id(self): None}
        nodes = [self]
        root = None

        while nodes:
            node = nodes.pop()
            if node.label == from_node and root is None:
                root = node

            for child in node.children:
                child_id = id(child)
                if child_id not in parents:
                    parents[child_id] = node
                    nodes.append(child)

        if root is None:
            raise ValueError(f"Node {from_node!r} is not in the tree")

        def rebuild(node, previous):
            """Copy the undirected tree while avoiding the edge just used."""
            neighbours = []

            parent = parents[id(node)]
            if parent is not None and parent is not previous:
                neighbours.append(parent)

            neighbours.extend(
                child for child in node.children if child is not previous
            )

            return Tree(
                node.label,
                [rebuild(neighbour, node) for neighbour in neighbours],
            )

        return rebuild(root, None)

    def path_to(self, from_node, to_node):
        """Return the labels on the path from ``from_node`` to ``to_node``."""
        tree = self.from_pov(from_node)
        stack = [(tree, [tree.label])]

        while stack:
            node, path = stack.pop()
            if node.label == to_node:
                return path

            for child in node.children:
                stack.append((child, path + [child.label]))

        # ``to_node`` can only be absent if the input is not a tree, but
        # raising explicitly makes the failure mode useful for callers.
        raise ValueError(f"Node {to_node!r} is not in the tree")

